import{_ as e,o as d,c as r,ai as a}from"./chunks/framework.Ba-VnP44.js";const m=JSON.parse('{"title":"CRM 客户关系管理系统","description":"","frontmatter":{},"headers":[],"relativePath":"instances/business/crm.md","filePath":"instances/business/crm.md"}'),o={name:"instances/business/crm.md"};function i(s,t,c,n,l,p){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="crm-客户关系管理系统" tabindex="-1">CRM 客户关系管理系统 <a class="header-anchor" href="#crm-客户关系管理系统" aria-label="Permalink to “CRM 客户关系管理系统”">​</a></h1><blockquote><p>OpenBiz 第 4 个独立消费者：客户主数据 + 商机状态机 + 销售漏斗统计的最小闭环。 ✅ 已验证 · 所属 <a href="/my-vitepress-site/instances/business/">03 企业业务应用</a> · 模块内优先级 2 · 代码 <code>E:/8.cangku/for-job/openbiz-crm-app</code></p></blockquote><h2 id="功能清单" tabindex="-1">功能清单 <a class="header-anchor" href="#功能清单" aria-label="Permalink to “功能清单”">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>状态</th><th>能做什么</th><th>证据</th></tr></thead><tbody><tr><td>客户档案</td><td>✅</td><td>建客户(NEW) → 激活(ACTIVE) → 流失(CHURNED)；活动态可转 INVALID 做逻辑删除</td><td>客户状态机 E2E 通过</td></tr><tr><td>商机管理</td><td>✅</td><td><code>DRAFT → NEGOTIATING → WON</code>；<code>DRAFT/NEGOTIATING → CANCELLED</code>；<code>DRAFT → NEGOTIATING → LOST</code>；WON/LOST/CANCELLED 为终态</td><td>商机状态机 E2E 通过</td></tr><tr><td>销售漏斗统计</td><td>✅</td><td><code>GET /api/crm/opportunities/stats</code> 按阶段聚合商机数与金额</td><td>E2E 校验阶段数字正确</td></tr><tr><td>非法流转拦截</td><td>✅</td><td>WON 再谈判、NEW 直接流失均被拒</td><td>返回 <code>ILLEGAL_TRANSITION</code></td></tr><tr><td>多租户</td><td>✅</td><td>复用 <code>openbiz-saas-core</code> 多租户 + RuoYi 登录外壳</td><td>端口 18084 + 独立库 <code>openbiz_crm</code></td></tr><tr><td>销售线索</td><td>📋</td><td>原规划有，实际未建表 —— 客户与商机之间缺线索层</td><td>待补充</td></tr><tr><td>客户跟进</td><td>📋</td><td>跟进记录、下次联系提醒、沟通时间线均未实现</td><td>待补充</td></tr></tbody></table><h2 id="待完善" tabindex="-1">待完善 <a class="header-anchor" href="#待完善" aria-label="Permalink to “待完善”">​</a></h2><ul><li><strong>线索层缺失</strong>：客户直接跳商机，没有线索录入 / 来源追踪 / 分配回收，销售漏斗上游是断的</li><li><strong>客户主数据偏薄</strong>：只有基础字段，联系人、标签分类、查重合并都还在规划里</li><li><strong>权限只到登录级</strong>：复用 RuoYi 外壳，没有销售团队 / 角色的行级数据隔离</li><li><strong>统计只有当前快照</strong>：没有时间维度，看不出赢单率趋势与阶段停留时长</li></ul><h2 id="验证证据" tabindex="-1">验证证据 <a class="header-anchor" href="#验证证据" aria-label="Permalink to “验证证据”">​</a></h2><ul><li>闭环：登录 → 建客户(NEW) → 激活(ACTIVE) → 建商机(DRAFT) → 谈判(NEGOTIATING) → 赢单(WON) → 阶段统计 → 非法流转拦截 → 重拉数据</li><li>复用与自建：复用 <code>openbiz-saas-core</code>（TenantContext / 自动装配）；自建 <code>openbiz_crm_customer</code>、<code>openbiz_crm_opportunity</code> 表与 Mapper / Service / Controller</li><li>实证记录：<a href="/my-vitepress-site/apps/openbiz/crm/">OpenBiz 实战 › CRM</a></li><li>工程位置：<code>E:/8.cangku/for-job/openbiz-crm-app</code>（端口 18084，含 README 与 E2E 脚本）</li></ul><hr><p>上一级：<a href="/my-vitepress-site/instances/business/">03 企业业务应用</a> · <a href="/my-vitepress-site/instances/">实例总览</a></p>',10)])])}const b=e(o,[["render",i]]);export{m as __pageData,b as default};
